// Порядок из консоли: 1 2 3 4 5/6 (5 и 6 зависят от старта таймера) 7

export function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const t = setTimeout(resolve, ms);
    signal?.addEventListener('abort', () => {
      clearTimeout(t);
      reject(signal.reason ?? new Error('aborted'));
    }, { once: true });
  });
}

/** Ретрай с exponential backoff + равномерный джиттер. */
export async function withRetry<T>(
  fn: (attempt: number) => Promise<T>,
  opts: { retries?: number; baseMs?: number; maxMs?: number; signal?: AbortSignal } = {},
): Promise<T> {
  const { retries = 4, baseMs = 200, maxMs = 5_000, signal } = opts;
  let lastErr: unknown;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastErr = err;
      if (signal?.aborted) throw err;
      if (attempt === retries) break;
      const exp = Math.min(maxMs, baseMs * 2 ** attempt);
      const jitter = Math.random() * exp * 0.3; // анти-синхронность ретраев
      await sleep(exp + jitter, signal);
    }
  }
  throw lastErr;
}

/** Таймаут поверх промиса: внешний вызов никогда не подвесит воркер. */
export function withTimeout<T>(p: Promise<T>, ms: number, label = 'op'): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`${label} timeout after ${ms}ms`)), ms);
    p.then(
      (v) => { clearTimeout(t); resolve(v); },
      (e) => { clearTimeout(t); reject(e); },
    );
  });
}

/** Простейший circuit breaker: closed -> open -> half-open -> closed. */
type State = 'closed' | 'open' | 'half-open';

export class CircuitBreaker {
  private state: State = 'closed';
  private failures = 0;
  private openedAt = 0;

  constructor(
    private readonly threshold = 5,
    private readonly resetMs = 30_000,
  ) {}

  async call<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === 'open') {
      if (Date.now() - this.openedAt < this.resetMs) {
        throw new Error('circuit is open: fast-fail');
      }
      this.state = 'half-open';
    }
    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  private onSuccess() { this.state = 'closed'; this.failures = 0; }
  private onFailure() {
    if (++this.failures >= this.threshold) {
      this.state = 'open';
      this.openedAt = Date.now();
    }
  }
}

import { createReadStream, createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
