  createWriteStream('app.log.gz'),
);

// 2) Пользовательский Transform: пакетная обработка строк лога
class JsonlToMetrics extends Transform {
  private buf = '';
  _transform(chunk: Buffer, _enc: string, cb: (e?: Error | null, d?: Buffer) => void) {
    this.buf += chunk.toString('utf8');
    const lines = this.buf.split('\n');
    this.buf = lines.pop() ?? '';
    for (const line of lines) {
      if (!line.trim()) continue;
      const rec = JSON.parse(line);
      this.push(Buffer.from(`${rec.level}\t${rec.latencyMs}\n`));
    }
    cb();
  }
}

await pipeline(Readable.from(['{"level":"info","latencyMs":12}\n']), new JsonlToMetrics(), process.stdout);

