import { performance, monitorEventLoopDelay } from 'node:perf_hooks';

const h = monitorEventLoopDelay({ resolution: 10 });
h.enable();
setInterval(() => {
  const { rss, heapUsed, external } = process.memoryUsage();
  const elu = performance.eventLoopUtilization();
  log({
    rssMb: (rss / 1024 ** 2).toFixed(1),
    heapMb: (heapUsed / 1024 ** 2).toFixed(1),
    externalMb: (external / 1024 ** 2).toFixed(1),
    elu: elu.utilization.toFixed(3),
    loopP99Ms: (h.percentile(99) / 1e6).toFixed(2),
  });
  h.reset();
}, 10_000).unref();

// node:test + TypeScript через tsx: устойчивый клиент с таймаутом и ретраем
import { test, mock } from 'node:test';
import assert from 'node:assert/strict';
import { fetchWithPolicy } from '../src/http.js';

test('повторяет запрос при 503 и возвращает данные', async () => {
  let calls = 0;
  const fetchMock = mock.method(globalThis, 'fetch', async () => {
    calls++;
    return calls < 3
      ? new Response('unavailable', { status: 503 })
      : new Response(JSON.stringify({ ok: true }), { status: 200 });
  });

  const res = await fetchWithPolicy('https://api.test/x', { retries: 3, timeoutMs: 500 });
  assert.deepEqual(await res.json(), { ok: true });
  assert.equal(calls, 3);
  fetchMock.mock.restore();
});

import { createServer } from 'node:http';

type Handler = (req: ReqCtx) => Promise<unknown> | unknown;
interface ReqCtx { url: URL; params: Record<string, string>; query: URLSearchParams; body: unknown }

const routes: Array<{ method: string; re: RegExp; handler: Handler }> = [];
const route = (method: string, path: string, handler: Handler) =>
  routes.push({ method, re: new RegExp('^' + path.replace(/:\w+/g, '(?<\\w>[^/]+)') + '$'), handler });

route('GET', '/users/:id', ({ params }) => db.findUser(params.id));

const server = createServer(async (req, res) => {
  const url = new URL(req.url!, 'http://localhost');
  const match = routes.find(r => r.method === req.method && r.re.test(url.pathname));
  if (!match) { res.writeHead(404).end(JSON.stringify({ error: 'not_found' })); return; }
  const m = url.pathname.match(match.re)!;
  const body = await readJson(req); // ограниченный размер (например, 1 МБ)
  try {
    const data = await match.handler({ url, params: m.groups ?? {}, query: url.searchParams, body });
    res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify(data));
  } catch (e) {
    res.writeHead(500).end(JSON.stringify({ error: 'internal' })); // и лог с correlation id
  }
});

// Graceful shutdown: новые запросы не принимаются, активные дорабатывают
const shutdown = (signal: string) => {
  console.log(signal, 'closing...');
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(1), 15_000).unref(); // страховка
};
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
server.listen(3000);
